Definition sl_live (sel data sy sx : Z) (rows : list Z) (live : list (Z * Z)) : list (Z * Z) :=
  rev (map (fun r => (r, 4 * sx)) rows) ++ (data, 8 * sy) :: (sel, 32) :: live.
Definition sl_chunks (sel data sy sx : Z) (rows : list Z) : list (Z * Z) :=
  (sel, 32) :: (data, 8 * sy) :: map (fun r => (r, 4 * sx)) rows.
